bool wrap_valid(std::string text) {
    std::vector<char> stack;
    bool deep = false;
    for (size_t i = 0; i < text.size(); i++) {
        if (text[i] == '(') stack.push_back(text[i]);
        if (text[i] == ')') {
            if (stack.empty()) return false;
            stack.pop_back();
        }
        if (stack.size() > 16) deep = true;
    }
    return stack.empty() && !deep;
}
